void transport_history_based_single_particle(Particle& p)
{
  while (p.alive()) {
    p.event_calculate_xs();
    if (p.alive()) {
      p.event_advance();
    }
    if (p.alive()) {
      if (p.collision_distance() > p.boundary().distance()) {
        p.event_cross_surface();
      } else if (p.alive()) {
        p.event_collide();
      }
    }
    p.event_check_limit_and_revive();
  }
  p.event_death();
}

